def apply(root: Path) -> str | None:
    target = root / PATH
    text = target.read_text(encoding="utf-8")
    original = text
    for old, new, expected in REPLACEMENTS:
        count = text.count(old)
        if count != expected:
            raise RuntimeError(
                f"{PATH} replacement count mismatch: expected {expected}, got {count}"
            )
        text = text.replace(old, new)
    if text == original:
        return None
    target.write_text(text, encoding="utf-8")
    return PATH
